INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f8455191-ac40-4c0c-bec1-b628b7d118f1', 'b2b2b2b2-3030-4000-8000-000000000002', 20, 'Dia 20 — Vulnerabilidade', 'Semana 3: Reconstruir', '{"pch": "Temos esse tesouro em vasos de barro\u2026 Sua fragilidade n\u00e3o \u00e9 fraqueza \u2014 \u00e9 transpar\u00eancia.", "verse": "2Cor 4,7", "lectio": "Leia 2Cor 4,7-12. Poder na fragilidade.", "practice": "Compartilhe algo verdadeiro com algu\u00e9m de confian\u00e7a.", "question": "Com quem voc\u00ea pode ser vulner\u00e1vel?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;